import{_ as a,c as n,o as t,ag as i}from"./chunks/framework.Cycwnjj0.js";const u=JSON.parse('{"title":"001. Python Performance Backend Contract","description":"","frontmatter":{},"headers":[],"relativePath":"adr/001-python-performance-backend-contract.md","filePath":"adr/001-python-performance-backend-contract.md"}'),r={name:"adr/001-python-performance-backend-contract.md"};function o(s,e,c,l,d,p){return t(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="_001-python-performance-backend-contract" tabindex="-1">001. Python Performance Backend Contract <a class="header-anchor" href="#_001-python-performance-backend-contract" aria-label="Permalink to &quot;001. Python Performance Backend Contract&quot;">​</a></h1><p><strong>Status:</strong> Accepted <strong>Date:</strong> 2026-07-03</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><code>@sylphx/webgpu</code> is the native Rust/wgpu WebGPU package used by TypeScript consumers that need GPU compute in Node.js and Bun. SylphxAI&#39;s numerical and ML libraries are moving toward Python-compatible syntax, behavior, and performance. This package is part of that strategy, but it is not itself a NumPy or PyTorch API layer.</p><p>The repository must stay consumer-neutral. It should provide standard WebGPU behavior and reproducible native package evidence without encoding one numerical library&#39;s benchmark story or hidden workload assumptions.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p><code>@sylphx/webgpu</code> is the backend substrate for Python-class GPU performance in TypeScript runtimes.</p><ul><li>This package owns standards-aligned WebGPU behavior, native Rust/wgpu bindings, platform packages, TypeScript declarations, docs, tests, and release evidence.</li><li>This package does not own NumPy/PyTorch syntax, tensor semantics, autograd semantics, or numerical-library admission gates.</li><li>Numerical libraries such as tsnum and Axon may use this package as a GPU backend, but their Python API and performance parity claims must be proven in those repositories.</li><li>This package may expose standard WebGPU async boundaries such as adapter acquisition, device acquisition, buffer mapping, and command completion. Numerical consumers should not leak those boundaries into every tensor operation; they should expose synchronous handles and explicit <code>sync</code> or readback awaits.</li><li><code>@sylphx/webgpu</code> performance claims must be stated as WebGPU/backend claims: dispatch overhead, buffer transfer behavior, shader execution capability, supported platforms, and native artifact compatibility.</li><li>Consumer benchmarks may cite <code>@sylphx/webgpu</code> backend identity only when the benchmark records package version, platform package, adapter/backend info, and workload shape.</li></ul><h2 id="rationale" tabindex="-1">Rationale <a class="header-anchor" href="#rationale" aria-label="Permalink to &quot;Rationale&quot;">​</a></h2><ul><li>Python-class numerical performance requires a native/GPU substrate, and this package provides that substrate for Node.js and Bun.</li><li>API parity belongs to the numerical/ML library, not the WebGPU package.</li><li>Standard WebGPU async semantics are correct at this layer, while Python-native numerical DX needs a higher-level queue abstraction.</li><li>Keeping the backend consumer-neutral preserves reuse across rendering, compute, ML, and non-ML workloads.</li><li>Recording backend identity prevents vague &quot;GPU is fast&quot; claims that cannot be reproduced.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Positive:</strong></p><ul><li>tsnum and Axon can depend on a clear GPU backend boundary.</li><li>The WebGPU package avoids coupling to one product workload.</li><li>Benchmark evidence can separate backend capability from higher-level tensor library semantics.</li></ul><p><strong>Negative:</strong></p><ul><li><code>@sylphx/webgpu</code> alone cannot prove Python parity for a numerical library.</li><li>Consumers must build their own workload-specific benchmark gates.</li><li>Backend performance docs need adapter/platform metadata to be admissible.</li></ul><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><p>Backend validation remains the package&#39;s existing native/test/release path:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>For parity claims in numerical consumers, run the consumer repository&#39;s Python parity benchmark instead.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Project boundary: <code>PROJECT.md</code></li><li>Project manifest: <code>.doctrine/project.json</code></li><li>Performance guide: <code>docs/guide/performance.md</code></li><li>Consumer parity contracts: <code>SylphxAI/tsnum</code> and <code>SylphxAI/axon</code></li></ul>`,21)])])}const m=a(r,[["render",o]]);export{u as __pageData,m as default};
